corrected_code:
const { createClient } = require('redis');
const redisClient = createClient({ url: process.env.REDIS_CONNECTION });

app.get('/api/sessions/:sessionId/details', requireAuthHeader, async (req, res) => {
  const { sessionId } = req.params;

  const sessionJson = await redisClient.get(`user_session:${sessionId}`);
  if (!sessionJson) {
    return res.status(404).json({ message: 'Session expired or not found' });
  }

  const parsed = JSON.parse(sessionJson);
  if (parsed.userId !== req.user.id) {
    return res.status(403).json({ message: 'Access denied to target session details' });
  }

  return res.json({
    sessionId,
    clientIp: parsed.ipAddress,
    userAgent: parsed.userAgent,
    lastActivity: parsed.lastSeen,
    mfaVerified: parsed.isMfaVerified
  });
});
